parameters.jsCode:
const jobs = $('Get New Jobs').all();
const scored = $('Score & Draft').all();
const reviews = $input.all();
const candidateName = $('Candidate Profile').first().json.candidate_name;

const out = [];
for (let i = 0; i < jobs.length; i++) {
  const job = jobs[i].json || {};
  const s = (scored[i] && scored[i].json && scored[i].json.output) ? scored[i].json.output : {};
  const rRaw = (reviews[i] && reviews[i].json) ? reviews[i].json : {};
  const r = rRaw.output || {};
  const reviewerUnavailable = rRaw.error !== undefined || Object.keys(r).length === 0;
  out.push({
    json: {
      id: job.id,
      job_title: job.job_title,
      company: job.company,
      location: job.location,
      job_url: job.job_url,
      contact_email: job.contact_email || "",
      candidate_name: candidateName,
      fit_score: (s.fit_score !== undefined && s.fit_score !== null) ? s.fit_score : null,
      fit_reason: s.fit_reason || "",
      cover_letter: s.cover_letter || "",
      approved: reviewerUnavailable ? false : (r.approved === true),
      review_score: reviewerUnavailable ? null : ((r.score !== undefined && r.score !== null) ? r.score : null),
      review_note: reviewerUnavailable ? "Second-opinion reviewer unavailable." : (r.note || ""),
    },
    pairedItem: { item: i },
  });
}
return out;

// DRY RUN — this node ONLY logs/aggregates. It sends no email and writes no data.
const THRESHOLD = 50;
const rows = $input.all().map((it) => it.json || {});

let passedThreshold = 0;
let hadEmail = 0;
let wouldSend = 0;      // passes threshold AND reviewer approved AND has contact_email
let rejected = 0;       // everything that would NOT be sent
const passedList = [];
const wouldSendList = [];

for (const r of rows) {
  const score = (r.fit_score === 0 || r.fit_score) ? Number(r.fit_score) : -1;
  const hasEmail = !!(r.contact_email && String(r.contact_email).trim());
  const approved = r.approved === true;
  const passes = score >= THRESHOLD;

  if (passes) {
    passedThreshold++;
    passedList.push({ id: r.id, job_title: r.job_title, company: r.company, fit_score: score, review_score: r.review_score, approved, has_email: hasEmail, contact_email: r.contact_email || "", cover_letter_preview: String(r.cover_letter || "").slice(0, 400) });
  }
  if (hasEmail) { hadEmail++; }

  const gatePass = passes && approved && hasEmail;
  if (gatePass) {
    wouldSend++;
    wouldSendList.push({ id: r.id, job_title: r.job_title, company: r.company, contact_email: r.contact_email, fit_score: score });
  } else {
    rejected++;
  }
}

// Highest-scoring job overall (for cover-letter preview)
let top = null;
for (const r of rows) {
  const score = (r.fit_score === 0 || r.fit_score) ? Number(r.fit_score) : -1;
  if (!top || score > top._score) { top = { ...r, _score: score }; }
}

return [{ json: {
  DRY_RUN: true,
  emails_sent: 0,
  db_writes: 0,
  threshold: THRESHOLD,
  total_new_jobs: rows.length,
  passed_threshold: passedThreshold,
  had_recruiter_email: hadEmail,
  would_have_been_sent: wouldSend,
  rejected: rejected,
  would_send_list: wouldSendList,
  passed_jobs: passedList,
  highest_scoring_job: top ? {
    id: top.id, job_title: top.job_title, company: top.company,
    fit_score: top._score, review_score: top.review_score, approved: top.approved === true,
    has_email: !!(top.contact_email && String(top.contact_email).trim()),
    fit_reason: top.fit_reason || "",
    cover_letter_preview: String(top.cover_letter || "").slice(0, 1200)
  } : null
} }];
